import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { resolve } from '../src/config.mjs';
const defaults=JSON.parse(await readFile(new URL('../config/default.json',import.meta.url)));
const local=JSON.parse(await readFile(new URL('../config/local.json',import.meta.url)));
assert.deepEqual(resolve(defaults,local),{endpoint:'https://default.invalid',timeoutMs:2500});
console.log('precedence-pass');

import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
const script=await readFile(new URL('../scripts/validate.sh',import.meta.url),'utf8');
assert.ok(script.indexOf('node test/unit.mjs') < script.indexOf('sh scripts/check-local.sh'));
const result=spawnSync('/bin/sh',['scripts/validate.sh'],{encoding:'utf8'});
assert.equal(result.status,0,result.stderr);
assert.match(result.stdout,/unit-pass/);
assert.match(result.stdout,/local-pass/);
console.log('merge-pass');
